// The original template coordinates never change. The paper grows around them.
export const ORIGINAL_PAPER={x:0,y:0,width:1000,height:900};
export function validPaper(p){return p&&['x','y','width','height'].every(k=>Number.isFinite(p[k]))&&p.x<=0&&p.y<=0&&p.x>=-1000000&&p.y>=-1000000&&p.width>=1000&&p.height>=900&&p.width<=2001000&&p.height<=2000900&&p.x+p.width>=1000&&p.y+p.height>=900&&p.x+p.width<=1001000&&p.y+p.height<=1000900}
export function paperView(width,height,sheet=ORIGINAL_PAPER){const p=validPaper(sheet)?sheet:ORIGINAL_PAPER;const scale=Math.min(Math.max(1,width)/p.width,Math.max(1,height)/p.height);const w=Math.max(p.width,Math.max(1,width)/scale),h=Math.max(p.height,Math.max(1,height)/scale);return {x:p.x-(w-p.width)/2,y:p.y-(h-p.height)/2,width:w,height:h}}
export function paperPoint(x,y,rect,view){return {x:Math.max(-999900,Math.min(1000900,view.x+Math.max(0,Math.min(1,(x-rect.left)/rect.width))*view.width)),y:Math.max(-999900,Math.min(1000800,view.y+Math.max(0,Math.min(1,(y-rect.top)/rect.height))*view.height))}}
export function includePoint(sheet,point,padding=0){const p=validPaper(sheet)?sheet:ORIGINAL_PAPER;const x=Math.max(-1000000,Math.min(p.x,point.x-padding)),y=Math.max(-1000000,Math.min(p.y,point.y-padding)),right=Math.min(1001000,Math.max(p.x+p.width,point.x+padding)),bottom=Math.min(1000900,Math.max(p.y+p.height,point.y+padding));return {x:Math.floor(x),y:Math.floor(y),width:Math.ceil(right)-Math.floor(x),height:Math.ceil(bottom)-Math.floor(y)}}
export function rasterSize(view,max=2048){const scale=Math.min(1,max/Math.max(view.width,view.height));return {width:Math.max(1,Math.round(view.width*scale)),height:Math.max(1,Math.round(view.height*scale))}}
export function beginPaper(ctx,canvas,view){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.setTransform(canvas.width/view.width,0,0,canvas.height/view.height,-view.x*canvas.width/view.width,-view.y*canvas.height/view.height)}
export function paperMarkup(markup,view){return markup.replace(/viewBox="[^"]*"/,`viewBox="${view.x} ${view.y} ${view.width} ${view.height}"`)}
